import test from 'node:test';import assert from 'node:assert/strict';
import {newPolyArp,buildArpChord,arpEventsAtStep} from './poly-arp.js';
test('diatonic chords respond to key and scale',()=>{let a=newPolyArp();a.key=0;a.scale='MINOR';a.chord='TRIAD';assert.deepEqual(buildArpChord(a),[60,63,67]);a.key=2;a.scale='DORIAN';assert.deepEqual(buildArpChord(a),[62,65,69]);a.chord='SEVENTH';assert.equal(buildArpChord(a).length,4)});
test('up and down arp and 1/8 tempo division',()=>{let a=newPolyArp();a.enabled=true;a.octaves=1;a.rate='1/8';let n=arpEventsAtStep(a,60,0,.125);assert.equal(n.length,1);assert.equal(arpEventsAtStep(a,60,1,.125).length,0);assert.ok(arpEventsAtStep(a,60,2,.125)[0].note>n[0].note);a.direction='DOWN';assert.ok(arpEventsAtStep(a,60,0,.125)[0].note>arpEventsAtStep(a,60,2,.125)[0].note)});
test('1/32 note subdivision and rest/pitch',()=>{let a=newPolyArp();a.enabled=true;a.rate='1/32';a.cells[0].on=false;a.cells[1].shift=2;let x=arpEventsAtStep(a,60,0,.125);assert.equal(x.length,1);assert.equal(x[0].offset,.0625);assert.equal(x[0].note,65)});
test('4-step phrase cycles and events bounded',()=>{let a=newPolyArp();a.enabled=true;a.steps=4;a.octaves=4;a.direction='RANDOM';for(let i=0;i<64;i++){let ev=arpEventsAtStep(a,72,i,.125);assert.equal(ev.length,1);assert.ok(ev[0].note>=0&&ev[0].note<=127)}});

test('every arp note stays within selected key and scale',()=>{for(const key of [0,2,6,9])for(const scale of ['MAJOR','MINOR','DORIAN','PHRYGIAN','LYDIAN','HARM MINOR']){let arp=newPolyArp();arp.enabled=true;arp.key=key;arp.scale=scale;arp.direction='RANDOM';arp.steps=16;arp.octaves=4;arp.cells.forEach((cell,i)=>{cell.shift=(i%9)-4});for(let i=0;i<96;i++){let e=arpEventsAtStep(arp,60,i,.125);for(const event of e){const modes={MAJOR:[0,2,4,5,7,9,11],MINOR:[0,2,3,5,7,8,10],DORIAN:[0,2,3,5,7,9,10],PHRYGIAN:[0,1,3,5,7,8,10],LYDIAN:[0,2,4,6,7,9,11],'HARM MINOR':[0,2,3,5,7,8,11]};assert.ok(modes[scale].includes(((event.note-key)%12+12)%12),scale+': '+event.note)}}}});
